CREATE DEFINER=`root`@`localhost` PROCEDURE `AddressesGetById`(
    IN p_Id BIGINT UNSIGNED
)
BEGIN
    SELECT 
        a.Id,
        a.Maildrop,
        a.Street,
        a.Suite,
        a.ZipCode,
        z.City AS ZipCity,
        z.State AS ZipState,
        a.City,
        a.State,
        a.Country,
        a.AddressHash,
        a.Created,
        a.Updated
    FROM addresses a
    LEFT JOIN zip_codes z ON z.ZipCode = a.ZipCode
    WHERE a.Id = p_Id;
END ;;
DELIMITER ;
