        UPDATE care_plan_interventions
        SET
            Description   = p_Description,
            Frequency     = p_Frequency,
            TargetDate    = p_TargetDate,
            CompletedDate = v_final_completed,
            Status        = p_Status
        WHERE Id = p_Id;

        SET p_Success = TRUE;
    END IF;

