    OUT p_PatientId BIGINT UNSIGNED,
    OUT p_VisitId BIGINT UNSIGNED,
    OUT p_BillingCodeId BIGINT UNSIGNED,
    OUT p_ChargeDate DATETIME,
    OUT p_Amount DECIMAL(10,2),
    OUT p_Notes TEXT,
    OUT p_Active BOOLEAN,
    OUT p_Found BOOLEAN
)
BEGIN
    DECLARE v_is_valid BOOLEAN DEFAULT TRUE;

    SET p_PatientId = NULL;
    SET p_VisitId = NULL;
    SET p_BillingCodeId = NULL;
    SET p_ChargeDate = NULL;
    SET p_Amount = NULL;
    SET p_Notes = NULL;
    SET p_Active = NULL;
    SET p_Found = FALSE;

    IF p_Id IS NULL OR p_Id = 0 THEN
        SET v_is_valid = FALSE;
    END IF;

    IF v_is_valid THEN
        SELECT
            PatientId,
            VisitId,
            BillingCodeId,
            ChargeDate,
            Amount,
            Notes,
            Active
        INTO
            p_PatientId,
            p_VisitId,
            p_BillingCodeId,
            p_ChargeDate,
            p_Amount,
            p_Notes,
            p_Active
        FROM charges
        WHERE Id = p_Id;

        IF p_PatientId IS NOT NULL THEN
            SET p_Found = TRUE;
        END IF;
    END IF;

END ;;
