    IF v_is_valid THEN
        UPDATE diagnosis_codes
        SET Active = FALSE
        WHERE Id = p_Id;

        SET p_Success = TRUE;
        SET p_Message = 'Diagnosis code deactivated';
    END IF;

END ;;
