CREATE DEFINER=`root`@`localhost` PROCEDURE `ImagingFilesCreate`(
    IN p_SeriesId BIGINT UNSIGNED,
    IN p_StudyId BIGINT UNSIGNED,
    IN p_FilePath VARCHAR(500),
    IN p_FileType ENUM('DICOM','JPEG','PNG','MP4'),
