CREATE DEFINER=`root`@`localhost` PROCEDURE `ImagingFilesSearchPath`(
    IN p_Search VARCHAR(255)
)
BEGIN
    DECLARE v_Search VARCHAR(255);

    IF p_Search IS NULL OR p_Search = '' THEN
        SET v_Search = NULL;
    ELSE
        SET v_Search = CONCAT('%', p_Search, '%');
    END IF;

    SELECT *
    FROM imaging_files
    WHERE
