    IN p_Id BIGINT UNSIGNED,
    IN p_Subject VARCHAR(200),
    IN p_MessageBody TEXT,
    IN p_ReadFlag TINYINT(1)
)
BEGIN
    DECLARE v_Error TEXT DEFAULT NULL;

    IF p_Id IS NULL OR p_Id = 0 THEN
        SET v_Error = 'Invalid Id';
    END IF;

