        SET v_Error = 'MedicationId is required';
    END IF;

    IF v_Error IS NULL AND p_DatePrescribed IS NULL THEN
        SET v_Error = 'DatePrescribed is required';
    END IF;

    IF v_Error IS NULL THEN
