    IN p_PerformedBy BIGINT UNSIGNED,
    IN p_ProcedureDate DATETIME,
    IN p_AnesthesiaUsed VARCHAR(255),
    IN p_EstimatedBloodLoss VARCHAR(50),
    IN p_Complications TEXT,
