        VALUES
        (p_PatientId, p_VisitId, p_ProcedureTypeId, p_PerformedBy, p_ProcedureDate,
         p_AnesthesiaUsed, p_EstimatedBloodLoss, p_Complications, p_Outcome, p_Notes);

